    cols = len(grid[0])
    counts = Counter([v for row in grid for v in row])
    background = counts.most_common(1)[0][0]

    result = {(r_mod, c): [] for r_mod in range(3) for c in range(cols)}

    for r in range(rows):
        r_mod = r % 3
        for c in range(cols):
            val = grid[r][c]
            if val != background:
                result[(r_mod, c)].append(val)

    # Now determine the "winner" value for each (r_mod, c)
    output = {}
    for (r_mod, c), vals in result.items():
        if not vals:
            output[(r_mod, c)] = background  # No non-bg, use background
        elif len(set(vals)) == 1:
            # All non-bg values are the same
            output[(r_mod, c)] = vals[0]
